old_text:
// Dragon fire run: at the start of the battle it comes in from beyond the enemy's edge, flies low and fast over the enemy's side
// to the middle of the field, turns and flies back out the way it came, then returns a moment later and fights as normal.
// Over the enemy's side it leaves a streak of fire on the ground that burns for 5 seconds. Any enemy on the ground that touches it
// catches fire: 5 damage a second while the streak lasts and for 5 seconds after it goes out.
function swoopStep(f,dt){
  const S=f.swoop, T=f.T, Z=T.swoop, dir=f.team===HOLD?1:-1, mid=AW/2, R0=Z.turnR, sp=T.speed*Z.mult;
  const out=dir>0?AW+T.w*0.6:-T.w*0.6;
  f.target=null; f.engaged=false; f.lunge=-1;
  if(S.st===0){   // line up on the enemy army (the middle of it, top to bottom), turning toward the roomier side
    const ys=F.filter(o=>o.team!==f.team&&!o.dead&&!o.T.flying).map(o=>o.y).sort((a,b)=>a-b);
    const lo=f.h+3, hi=AH-3;
    S.y1=Math.max(lo,Math.min(hi,ys.length?ys[ys.length>>1]:AH/2));
    S.up=S.y1+2*R0<=hi?1:-1; S.cy=S.y1+S.up*R0; S.a=0;
    f.x=out; f.y=S.y1; S.st=1; S.drop=0; S.px=f.x; S.py=f.y; }
  let nx=f.x, ny=f.y;
  if(S.st===1){ nx=f.x-dir*sp*dt; if((nx-mid)*dir<=0){ nx=mid; S.st=2; } }                      // in over the enemy's side
  else if(S.st===2){ S.a=Math.min(Math.PI,S.a+sp/R0*dt);                                           // the turn
    nx=mid-dir*R0*Math.sin(S.a); ny=S.cy-S.up*R0*Math.cos(S.a); if(S.a>=Math.PI) S.st=3; }
  else if(S.st===3){ nx=f.x+dir*sp*dt; if((nx-out)*dir>=0){ nx=out; S.st=4; S.t=0; } }             // back out
  else { S.t+=dt; if(S.t>=Z.wait) f.swoop=null; f.vx=0; f.vy=0; f.walking=true; return; }        // off the edge a moment, then back to fight
  f.vx=nx-f.x; f.vy=ny-f.y; f.walking=true; f.phase+=dt*9; if(Math.abs(f.vx)>1e-4) f.face=f.vx>0?1:-1;
  // fire on the ground behind it, while it's over the enemy's side of the field
  const onTheirSide=(nx-mid)*dir>0.5&&nx>0&&nx<AW;
  S.drop+=Math.hypot(nx-S.px,ny-S.py); S.px=nx; S.py=ny;
  if(onTheirSide&&S.drop>=Z.fire.gap){ S.drop=0; dropFire(f,nx,ny); }
}

new_text:
// Dragon fire run: at the start of the battle it takes off from behind its own edge and flies low and very fast (6x its flying speed)
// straight across the field, along the middle of the enemy army, and out past the enemy's edge. Over the enemy's side it leaves a
// streak of fire on the ground that burns for 5 seconds. Any enemy on the ground that touches it catches fire: 5 damage a second
// while the streak lasts and for 5 seconds after it goes out. A moment later it comes back on from its own edge, glides down to
// land in front of its army and then fights as normal.
function swoopStep(f,dt){
  const S=f.swoop, T=f.T, Z=T.swoop, dir=f.team===HOLD?1:-1, mid=AW/2;
  const home=dir>0?-T.w:AW+T.w, out=dir>0?AW+T.w:-T.w;   // fully out of sight
  f.target=null; f.engaged=false; f.lunge=-1;
  if(S.st===0){   // line up on the middle of the enemy army (top to bottom), just behind its own edge
    const ys=F.filter(o=>o.team!==f.team&&!o.dead&&!o.T.flying).map(o=>o.y).sort((a,b)=>a-b);
    S.y1=Math.max(f.h+3,Math.min(AH-3,ys.length?ys[ys.length>>1]:AH/2));
    f.x=home; f.y=S.y1; S.st=1; S.drop=0; S.px=f.x; S.py=f.y; }
  let nx=f.x, ny=f.y;
  if(S.st===1){ nx=f.x+dir*T.speed*Z.mult*dt; if((nx-out)*dir>=0){ nx=out; S.st=2; S.t=0; } }          // the run, all the way across
  else if(S.st===2){ S.t+=dt; f.vx=0; f.vy=0; f.walking=true;                                           // off past the enemy's edge a moment
    if(S.t>=Z.wait){ S.st=3; f.x=home; f.y=S.y1; S.lx=dir>0?AW*Z.land:AW*(1-Z.land); S.px=f.x; S.py=f.y; }   // ...then back on from its own edge
    return; }
  else if(S.st===3){ const dx=S.lx-f.x, d=Math.abs(dx), st=T.speed*Z.back*dt;                          // glides in and lands in front of its army
    if(d<=st&&f.baseAlt<=LOW_ALT+0.4){ nx=S.lx; f.swoop=null; }
    else nx=f.x+Math.sign(dx)*Math.min(st,d); }
  f.vx=nx-f.x; f.vy=ny-f.y; f.walking=true; f.phase+=dt*9; if(Math.abs(f.vx)>1e-4) f.face=f.vx>0?1:-1;
  if(S.st!==1) return;
  // fire on the ground behind it, while it's over the enemy's side of the field
  const onTheirSide=(nx-mid)*dir>0.5&&nx>0&&nx<AW;
  S.drop=onTheirSide?S.drop+Math.hypot(nx-S.px,ny-S.py):0; S.px=nx; S.py=ny;   // (only counts distance flown over their side)
  while(onTheirSide&&S.drop>=Z.fire.gap){ S.drop-=Z.fire.gap; dropFire(f,nx-dir*S.drop,ny); }   // (fast enough to need several a frame)
}
